import typer

app = typer.Typer()


@app.callback()
def main():
    """Greeting CLI."""


@app.command()
def greet(name: str, loud: bool = False):
    if loud:
        typer.echo(f'Hello, {name}!'.upper())
    else:
        typer.echo(f'Hello, {name}!')


if __name__ == '__main__':
    app()

